function live(type){return records.filter(r=>r.type===type&&!r.deletedAt&&(currentRole==='admin'||recordWithinScopes(r,currentScopes)));}
function recordWithinScopes(r,scopes=currentScopes){const d=r.data||{};if(r.type==='school')return scopes.some(s=>s.schoolId===r.id);if(r.type==='subject')return scopes.some(s=>s.subjectId===r.id);if(r.type==='course')return scopes.some(s=>s.courseId===r.id);if(r.type==='division')return scopes.some(s=>s.divisionId===r.id);if(r.type==='subgroup')return scopes.some(s=>exactScope(d,s)||(!d.schoolId&&!d.subjectId&&!d.courseId&&s.divisionId===d.divisionId));if(r.type==='membership')return scopes.some(s=>scopeMatches(d,s));if(r.type==='student')return records.some(m=>m.type==='membership'&&m.data.studentId===r.id&&scopes.some(s=>scopeMatches(m.data,s)));if(r.type==='grade'){const a=records.find(x=>x.type==='assessment'&&x.id===d.assessmentId);return !!a&&recordWithinScopes(a,scopes)&&records.some(m=>m.type==='membership'&&m.data.studentId===d.studentId&&scopes.some(s=>scopeMatches(m.data,s)));}if(['assessment','schedule','attendance','observation','topic'].includes(r.type))return scopes.some(s=>scopeMatches(d,s))&&(!d.studentId||records.some(m=>m.type==='membership'&&m.data.studentId===d.studentId&&scopes.some(s=>scopeMatches(m.data,s))));if(r.type==='scale'||r.type==='cutoff')return scopes.some(s=>scopeMatches(d,s))||records.some(a=>a.type==='assessment'&&(r.type==='scale'?a.data.scaleId===r.id:a.data.cutoffId===r.id)&&scopes.some(s=>scopeMatches(a.data,s)));return false;}
