function sessionMemberships(schedule){return live('membership').filter(m=>{const journey=typeof Trajectory!=='undefined'?Trajectory.activeJourneys(records,m.data.studentId)[0]:null;return(!journey||journey.data.schoolId===m.data.schoolId&&journey.data.courseId===m.data.courseId&&journey.data.divisionId===m.data.divisionId)&&m.data.schoolId===schedule.data.schoolId&&m.data.subjectId===schedule.data.subjectId&&m.data.courseId===schedule.data.courseId&&m.data.divisionId===schedule.data.divisionId;});}
function sessionRoster(schedule){const ids=new Set(sessionMemberships(schedule).map(x=>x.data.studentId)),cohort=$('#filter-cohort')?.value||'';return live('student').filter(x=>ids.has(x.id)&&(!cohort||sessionMemberships(schedule).some(m=>m.data.studentId===x.id&&String(m.data.cohortYear||'')===cohort))).sort((a,b)=>a.data.fullName.localeCompare(b.data.fullName,'es'));}
function displayScale(a){return getOne('scale',a.data.scaleId)?.data||{min:1,max:10,mode:'numeric',intervals:[]};}
function tableSearchMatches(text,query){return String(text||'').toLocaleLowerCase('es').includes(String(query||'').trim().toLocaleLowerCase('es'));}
function tableRowSearchMatches(row,query,column=''){return tableSearchMatches(column===''?row.textContent:row.cells[Number(column)]?.innerText,query);}
