function validAssessmentDate(value){if(!value)return true;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number.isNaN(Date.parse(value+'T00:00:00Z')))return false;return new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;}
