function inputField(name,label,type='text',value='',required=true,attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attrs}></label>`;}
function selectField(name,label,list,{required=true,multiple=false,selected=''}={}){const selectedValues=new Set(Array.isArray(selected)?selected:[selected]);return `<label>${label}<select name="${name}" ${required?'required':''} ${multiple?'multiple':''}><option value="">${multiple?'(ninguno)':`Elegí ${label.toLowerCase()}`}</option>${list.map(x=>`<option value="${esc(x.id)}" ${selectedValues.has(x.id)?'selected':''}>${esc(x.data.name||x.data.fullName||x.id)}</option>`).join('')}</select></label>`;}
function scheduleSlotsMarkup(slots=[{}]){return slots.map((x,i)=>`<fieldset class="schedule-slot"><legend>Sesión ${i+1}</legend><div class="two-col">${selectField('slotDay','Día',[{id:'1',data:{name:'Lunes'}},{id:'2',data:{name:'Martes'}},{id:'3',data:{name:'Miércoles'}},{id:'4',data:{name:'Jueves'}},{id:'5',data:{name:'Viernes'}},{id:'6',data:{name:'Sábado'}},{id:'0',data:{name:'Domingo'}}],{selected:String(x.dayOfWeek??'')})}${inputField('slotStart','Desde','time',x.startTime||'')}${inputField('slotEnd','Hasta','time',x.endTime||'')}</div><button type="button" class="quiet-button danger-button" data-remove-schedule-slot>Quitar sesión</button></fieldset>`).join('');}
function normalizeScheduleSlots(values){const days=values.slotDay||[],starts=values.slotStart||[],ends=values.slotEnd||[],slots=days.map((day,i)=>({dayOfWeek:day===''?NaN:Number(day),startTime:String(starts[i]||''),endTime:String(ends[i]||'')}));if(!slots.length||slots.some(x=>!Number.isInteger(x.dayOfWeek)||x.dayOfWeek<0||x.dayOfWeek>6||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.startTime)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.endTime)||x.startTime>=x.endTime))throw Error('Completá cada día y una franja horaria válida.');for(let i=0;i<slots.length;i++)for(let j=0;j<i;j++)if(slots[i].dayOfWeek===slots[j].dayOfWeek&&slots[i].startTime<slots[j].endTime&&slots[j].startTime<slots[i].endTime)throw Error('Las sesiones que agregaste se superponen.');return slots;}
