function openStudentGradebook(id){const st=getOne('student',id);if(!st)return;const rows=[];for(const m of live('membership').filter(x=>x.data.studentId===id)){const d=m.data,sub=live('subject').find(x=>x.id===d.subjectId),assessments=live('assessment').filter(a=>['schoolId','subjectId','courseId','divisionId'].every(k=>a.data[k]===d[k])),slots=live('schedule').filter(x=>['schoolId','subjectId','courseId','divisionId'].every(k=>x.data[k]===d[k])).sort((x,y)=>Number(x.data.dayOfWeek)-Number(y.data.dayOfWeek)||x.data.startTime.localeCompare(y.data.startTime)),teacherSlots=slots.map(x=>`${esc(teachers.find(t=>t.teacherId===x.data.teacherId)?.name||'Sin docente asignado')} · ${['domingo','lunes','martes','miércoles','jueves','viernes','sábado'][Number(x.data.dayOfWeek)]} ${esc(x.data.startTime)}–${esc(x.data.endTime)}`).join('<br>')||'Sin horario';if(!assessments.length)rows.push(`<tr><td>${esc(sub?.data.name||d.subjectId)} · ${esc(scopeLabel(d))}</td><td>${teacherSlots}</td><td>—</td><td>—</td><td>—</td><td>Sin instancias</td></tr>`);for(const a of assessments){const g=live('grade').find(x=>x.data.studentId===id&&x.data.assessmentId===a.id);rows.push(`<tr><td>${esc(sub?.data.name||d.subjectId)} · ${esc(scopeLabel(d))}</td><td>${teacherSlots}</td><td>${esc(a.data.name)}</td><td>${esc(formatDateShort(a.data.date)||'—')}</td><td>${esc(g?.data.value??'—')}</td><td>${esc(STATUSES[g?.data.status]||'Pendiente')}</td></tr>`);}}$('#student-gradebook-title').textContent=`Libreta · ${st.data.fullName}`;$('#student-gradebook-rows').innerHTML=rows.join('')||'<tr><td colspan="6" class="empty">Sin materias asignadas.</td></tr>';$('#student-gradebook-dialog').showModal();}
function openStudentRecords(id,kind){const st=getOne('student',id);if(!st)return;const ms=live('membership').filter(x=>x.data.studentId===id),contexts=new Set(ms.map(m=>[m.data.schoolId,m.data.subjectId,m.data.courseId,m.data.divisionId].join('|'))),items=kind==='attendance'?live('attendance').filter(x=>x.data.studentId===id):live('observation').filter(x=>x.data.studentId===id||(!x.data.studentId&&contexts.has([x.data.schoolId,x.data.subjectId,x.data.courseId,x.data.divisionId].join('|'))));$('#student-records-title').textContent=`${kind==='attendance'?'Asistencia':'Observaciones'} · ${st.data.fullName}`;$('#student-records-rows').innerHTML=items.map(x=>`<tr><td>${esc(formatDateShort(x.data.date))}</td><td>${esc(scopeLabel(x.data))}</td><td>${esc(kind==='attendance'?(x.data.status==='present'?'Presente':'Ausente'):(x.data.title||x.data.text))}</td><td>${kind==='attendance'?(live('schedule').find(y=>y.id===x.data.scheduleId)?esc(scheduleLabel(live('schedule').find(y=>y.id===x.data.scheduleId))):''):''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Sin registros.</td></tr>';$('#student-gradebook-dialog').close?.();$('#student-records-dialog').showModal();}
$('#student-cards').addEventListener('click',async e=>{const b=e.target.closest('[data-student-action]');if(!b)return;const studentId=b.dataset.student;if(b.dataset.studentAction==='topic'){const current=selected(),keys={school:'schoolId',subject:'subjectId',course:'courseId',division:'divisionId'},m=live('membership').find(x=>x.data.studentId===studentId&&['school','subject','course','division'].every(k=>x.data[keys[k]]===current[k]))||live('membership').find(x=>x.data.studentId===studentId);if(m){for(const k of ['school','subject','course','division'])$(`#filter-${k}`).value=m.data[{school:'schoolId',subject:'subjectId',course:'courseId',division:'divisionId'}[k]]||'';render();}document.querySelector('.sidebar-link[data-tab="topic"]')?.click();return;}if(currentRole==='admin'&&!teachers.length)await loadTeachers().catch(()=>{});if(b.dataset.studentAction==='libreta')openStudentGradebook(studentId);else openStudentRecords(studentId,b.dataset.studentAction);});$('[data-student-dialog-close]')?.addEventListener('click',()=>$('#student-gradebook-dialog').close());$('[data-student-records-close]')?.addEventListener('click',()=>$('#student-records-dialog').close());
$('#import-admin-xlsx')?.addEventListener('click',()=>{if(currentRole!=='admin')return toast('Solo administración puede importar registros.','error');$('#xlsx-file').click();});$('#export-admin-xlsx')?.addEventListener('click',()=>{if(currentRole!=='admin')return toast('Solo administración puede exportar registros.','error');exportAdminWorkbookOnly();});$('#import-xlsx').onclick=()=>$('#xlsx-file').click();$('#xlsx-file').onchange=e=>{const file=e.target.files?.[0];e.target.value='';if(file){if(!sessionToken){toast('Iniciá sesión para importar en Sheets.','error');return;}loadRemote().then(()=>importWorkbook(file)).catch(()=>{});}};$$('[data-import-close]').forEach(button=>button.onclick=()=>$('#import-dialog').close());$('#import-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const changes=[];for(let i=0;i<importCandidates.length;i++){const choice=$(`[data-import="${i}"]`).value,x=importCandidates[i];if(choice==='keep'||choice==='skip')continue;try{const data=JSON.parse($(`[data-import-json="${i}"]`).value),r={...x.item,data,expectedVersion:Number(x.existing?.expectedVersion||0),syncState:'synced',updatedAt:new Date().toISOString()};validateRecord(r);changes.push(r);}catch(err){toast(`Fila ${x.index}: ${err.message||'contenido inválido'}`,'error');return;}}validateImportRelationships(importCandidates.map((x,i)=>({...x,choice:$(`[data-import="${i}"]`).value,item:changes.find(r=>r.recordId===x.item.recordId)||x.item})));validateImportRelationships(changes.map(r=>({item:r,choice:'file',index:1})));if(!confirm(`¿Preparar ${changes.length} registro(s)? Se enviarán a Sheets solo al tocar “Sincronizar”.`))return;try{await saveRecords(changes);$('#import-dialog').close();render();toast(`${changes.length} registro(s) preparados. Tocá “Sincronizar con Sheets”.`);}catch(err){toast('No se pudieron preparar los registros: '+err.message,'error');}finally{if(submit)submit.disabled=false;}};
window.addEventListener('online',async()=>{if(!sessionToken)return;try{if(!stageOwner&&currentUsername)stageOwner=await stageOwnerKey(currentUsername);await restoreStage();updateSyncUI();await loadRemote();toast(stagedRecords.size?'Conexión restablecida. Tus cambios siguen pendientes; revisalos y tocá Sincronizar.':'Conexión restablecida.','success');}catch(e){updateSyncUI();}});window.addEventListener('offline',()=>{$('#connection').textContent='Sin conexión a Sheets';$('#connection').className='connection offline';updateSyncUI();});
initializeClassContextControls();
(async()=>{$('#connection').textContent='Iniciá sesión para conectar con Sheets';$('#connection').className='connection offline';if(sessionToken&&currentUsername){try{stageOwner=await stageOwnerKey(currentUsername);await restoreStage();updateSyncUI();}catch(_){}}if(sessionToken){try{await loadRemote();}catch(e){updateSyncUI();}}})();
['cycle','cohort','school','subject','course','division','student','from','to'].forEach(k=>{const el=$(`#summary-filter-${k}`);el.addEventListener('change',renderSummary);if(k==='student')el.addEventListener('input',renderSummary);});$('#summary-filter-clear').onclick=()=>{['cycle','cohort','school','subject','course','division','student','from','to'].forEach(k=>$(`#summary-filter-${k}`).value='');renderSummary();};$$('[data-summary-tab]').forEach(b=>b.onclick=()=>renderSummaryPanel(b.dataset.summaryTab));
